CSS += "\n/* OI-285 owner progress visibility */\n/* ============================================================\n   OAL Search — Run progress visibility (presentation only)\n   Paste at the END of the existing <style> block in\n   OAL_Search.en-US.webpage.copy.html\n   Applies ONLY while the job is queued/running. Idle,\n   completed, failed and stuck states stay exactly as-is.\n   No engine / R17-C0 logic is touched.\n   ============================================================ */\n\n/* smooth transition in and out of the run state */\n.oal-pct{\n  font-variant-numeric:tabular-nums;\n  transition:font-size .18s ease, color .18s ease, min-width .18s ease;\n}\n\n/* taller rail + a faint track for the progress bar */\n.oal-rail:has(#rs-badge.running),\n.oal-rail:has(#rs-badge.queued){\n  height:52px;\n  background:linear-gradient(rgba(255,138,69,.22),rgba(255,138,69,.22))\n             left bottom / 100% 7px no-repeat,\n             var(--oal-surface-2);\n}\n\n/* the percentage: 12px -> 26px, brand purple -> accent orange */\n.oal-rail:has(#rs-badge.running) .oal-pct,\n.oal-rail:has(#rs-badge.queued)  .oal-pct{\n  font-size:26px;\n  line-height:1;\n  min-width:88px;\n  letter-spacing:-.02em;\n  color:var(--oal-accent);\n  text-shadow:0 0 14px rgba(255,138,69,.45);\n}\n\n/* background fill: opacity .12 -> .30 + a bright leading edge */\n.oal-rail:has(#rs-badge.running)::before,\n.oal-rail:has(#rs-badge.queued)::before{\n  opacity:.30;\n  box-shadow:inset -1px 0 0 rgba(255,138,69,.9);\n}\n\n/* solid 7px progress bar along the bottom of the rail */\n.oal-rail:has(#rs-badge.running)::after,\n.oal-rail:has(#rs-badge.queued)::after{\n  content:\"\";\n  position:absolute;\n  inset-inline-start:0;\n  inset-block-end:0;\n  z-index:2;\n  height:7px;\n  width:var(--progress,0%);\n  min-width:2px;\n  background:linear-gradient(90deg,var(--oal-brand-2) 0%,var(--oal-accent) 100%);\n  border-start-end-radius:4px;\n  border-end-end-radius:4px;\n  box-shadow:0 0 10px rgba(255,138,69,.6);\n  transition:width .4s ease;\n  animation:oal-run-pulse 1.6s ease-in-out infinite;\n}\n\n@keyframes oal-run-pulse{0%,100%{opacity:1}50%{opacity:.72}}\n\n@media (prefers-reduced-motion:reduce){\n  .oal-rail:has(#rs-badge.running)::after,\n  .oal-rail:has(#rs-badge.queued)::after{animation:none}\n}\n\n";

CSS += "\n/* OI-287 Excel activity indicator (separate from owner progress CSS) */\n#oal-export.is-preparing::before,#oal-pdf.is-preparing::before{content:\"⟳\";display:inline-block;margin-inline-end:5px;animation:oal-excel-spin .8s linear infinite}\n@keyframes oal-excel-spin{to{transform:rotate(360deg)}}\n@media (prefers-reduced-motion:reduce){#oal-export.is-preparing::before,#oal-pdf.is-preparing::before{animation:none}}\n";

